import{createLogger,logError}from"#internal/logging.js";import{readDurableSession}from"#execution/durable-session-store.js";import{liveRuns}from"#execution/tasks/table.js";import{stopRuns}from"#execution/stop-runs.js";const log=createLogger(`execution.terminate-child-sessions`);async function terminateChildSessionsStep(e){"use step";let t;try{t=liveRuns(readDurableSession(e.sessionState).state)}catch(t){logError(log,`failed to read child sessions for termination`,t,{parentSessionId:e.sessionState.sessionId});return}await stopRuns(t.map(e=>({ends:!0,run:e})),{kind:`end`,reason:`The session ended.`})}async function reportChildSessionTeardownFailureStep(e){"use step";logError(log,`failed to terminate child sessions`,e.error,{parentSessionId:e.parentSessionId})}export{reportChildSessionTeardownFailureStep,terminateChildSessionsStep};